(function(root){
 'use strict';
 const F=root.Football||(typeof require==='function'?require('./engine.js'):null),E=root.Economy||(typeof require==='function'?require('./economy.js'):null),copy=x=>JSON.parse(JSON.stringify(x)),positions=['all','GK','DEF','MID','FW'],sorts=['position','club','cost','potential','primary','age','corner','freeKick','target'],ages=['all','u21','22-25','26-29','30+'],thresholds=[0,70,75,80,85],potentials=[0,85,90,95],sellerSlots={t_g1:0,t_g2:0,t_d1:1,t_d2:2,t_m1:3,t_m2:4,t_f1:5,t_f2:6};
 const seasonModule=()=>root.Season||(typeof require==='function'?require('./season.js'):null);
 function rivalClubs(s){const S=seasonModule();return S.leagueClubs(s).filter(club=>club.id!==S.own);}
 function sellerClub(s,identity){const rivals=rivalClubs(s);return rivals[sellerSlots[identity]??F.market.findIndex(p=>p.identity===identity)%Math.max(1,rivals.length)]||null;}
 function validate(s){
  const book=s.transferPlans;if(book===undefined)return s;
  if(!book||typeof book!=='object'||Array.isArray(book)||Object.keys(book).length!==2||book.version!==1||!Array.isArray(book.shortlist)||book.shortlist.length>F.market.length||new Set(book.shortlist).size!==book.shortlist.length||book.shortlist.some(id=>!F.market.some(p=>p.identity===id)))throw Error('저장한 영입 관심 목록을 읽을 수 없어요.');return s;
 }
 function toggle(s,identity){validate(s);if(!F.market.some(p=>p.identity===identity))throw Error('영입 시장의 후보를 선택하세요.');const next=copy(s),old=next.transferPlans?.shortlist||[],shortlist=old.includes(identity)?old.filter(id=>id!==identity):old.concat(identity);if(shortlist.length)next.transferPlans={version:1,shortlist};else delete next.transferPlans;return next;}
 function outgoingSlot(s,p,choices={}){const players=Object.values(s.squad).filter(x=>x.pos===p.pos),chosen=choices[p.identity];return players.some(x=>x.id===chosen)?chosen:[...players].sort((a,b)=>Number(s.match?.lineup.includes(a.id))-Number(s.match?.lineup.includes(b.id))||a[F.roleKey(a)]-b[F.roleKey(b)]||a.id.localeCompare(b.id))[0].id;}
 function search(s,filters={},choices={}){
  validate(s);filters=filters&&typeof filters==='object'?filters:{};const rivals=rivalClubs(s),position=positions.includes(filters.position)?filters.position:'all',seller=typeof filters.sellerClub==='string'&&rivals.some(club=>club.id===filters.sellerClub)?filters.sellerClub:'all',sort=sorts.includes(filters.sort)?filters.sort:'position',ageGroup=ages.includes(filters.ageGroup)?filters.ageGroup:'all',primaryMin=thresholds.includes(Number(filters.primaryMin))?Number(filters.primaryMin):0,potentialMin=potentials.includes(Number(filters.potentialMin))?Number(filters.potentialMin):0,query=typeof filters.query==='string'?filters.query.trim().toLocaleLowerCase('ko-KR').slice(0,60):'',shortlistOnly=filters.shortlistOnly===true,affordableOnly=filters.affordableOnly===true,shortlist=s.transferPlans?.shortlist||[];
  const rows=F.market.map(p=>{const slot=outgoingSlot(s,p,choices),registered=Object.values(s.squad).find(x=>x.identity===p.identity),owned=!!registered,actual=registered||p,used=s.finance.marketUsed.includes(p.identity),quote=E.quote(s,p.identity,slot),club=sellerClub(s,p.identity),age=p.age+s.year-1;return {identity:p.identity,name:p.name,pos:p.pos,kind:p.kind,age,primary:actual[F.roleKey(actual)],potential:actual.potential,setPieces:Object.fromEntries(Object.keys(F.setPieceRoleNames).map(role=>[role,F.setPieceScore(actual,role)])),sellerClubId:club?.id||'',sellerClubName:club?.name||'',sellerClubShort:club?.short||'',slot,shortlisted:shortlist.includes(p.identity),owned,used,quote};}).filter(p=>{
   const ageMatch=ageGroup==='all'||ageGroup==='u21'&&p.age<=21||ageGroup==='22-25'&&p.age>=22&&p.age<=25||ageGroup==='26-29'&&p.age>=26&&p.age<=29||ageGroup==='30+'&&p.age>=30;
   return (position==='all'||p.pos===position)&&(seller==='all'||p.sellerClubId===seller)&&ageMatch&&p.primary>=primaryMin&&p.potential>=potentialMin&&(!query||[p.name,p.pos,p.kind,p.sellerClubName,p.sellerClubShort].some(x=>x.toLocaleLowerCase('ko-KR').includes(query)))&&(!shortlistOnly||p.shortlisted)&&(!affordableOnly||!p.owned&&!p.used&&p.quote.balanceAfter>=0);
  });
  rows.sort((a,b)=>Object.hasOwn(F.setPieceRoleNames,sort)?b.setPieces[sort]-a.setPieces[sort]||a.quote.cost-b.quote.cost||a.identity.localeCompare(b.identity):sort==='club'?a.sellerClubName.localeCompare(b.sellerClubName,'ko-KR')||positions.indexOf(a.pos)-positions.indexOf(b.pos):sort==='cost'?a.quote.cost-b.quote.cost||a.identity.localeCompare(b.identity):sort==='potential'?b.potential-a.potential||a.quote.cost-b.quote.cost:sort==='primary'?b.primary-a.primary||a.quote.cost-b.quote.cost:sort==='age'?a.age-b.age||b.potential-a.potential:positions.indexOf(a.pos)-positions.indexOf(b.pos)||F.market.findIndex(p=>p.identity===a.identity)-F.market.findIndex(p=>p.identity===b.identity));
  return {rows,total:F.market.length,shortlistCount:shortlist.length,clubs:rivals.map(({id,name,short})=>({id,name,short})),filters:{position,sellerClub:seller,sort,ageGroup,primaryMin,potentialMin,query,shortlistOnly,affordableOnly}};
 }
 function preview(s,identity,slot){
  const S=seasonModule(),next=S.recruit(s,identity,slot),incoming=F.identityProfile(identity),outgoing=s.squad[slot],quote=E.quote(s,identity,slot),key=F.roleKey(incoming);
  return {identity,slot,fingerprint:JSON.stringify(s),incoming:{identity,name:incoming.name,pos:incoming.pos,primary:incoming[key],potential:incoming.potential,wage:incoming.wage,setPieces:Object.fromEntries(Object.keys(F.setPieceRoleNames).map(role=>[role,F.setPieceScore(incoming,role)]))},outgoing:{identity:outgoing.identity,name:outgoing.name,pos:outgoing.pos,primary:outgoing[key],potential:outgoing.potential,xp:outgoing.xp,wage:F.identityProfile(outgoing.identity).wage,setPieces:Object.fromEntries(Object.keys(F.setPieceRoleNames).map(role=>[role,F.setPieceScore(outgoing,role)]))},releasedSetPieces:Object.keys(s.plan.setPieces||{}).filter(role=>s.plan.setPieces[role]===outgoing.identity),quote,starting:!!next.match.lineup.includes(slot),lineupChanged:JSON.stringify(next.match.lineup)!==JSON.stringify(s.match.lineup),academy:!!incoming.academy};
 }
 function confirm(s,identity,slot,fingerprint){if(typeof fingerprint!=='string'||fingerprint!==JSON.stringify(s))throw Error('구단 상태가 바뀌었습니다. 영입 내용을 다시 확인하세요.');return seasonModule().recruit(s,identity,slot);}
 const api={validate,toggle,outgoingSlot,search,preview,confirm};root.TransferPlans=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
